const mongoose = require('mongoose'); const bcrypt = require('bcryptjs'); mongoose.connect('mongodb://localhost:27017/nexora').then(async () => { const salt = await bcrypt.genSalt(10); const password = await bcrypt.hash('student123', salt); const res = await mongoose.connection.db.collection('users').updateMany({role: 'Student'}, {$set: {password}}); console.log('Updated ' + res.modifiedCount + ' students'); process.exit(0); }).catch(console.error);
